"""Tests of the hal_nxp pin multiplexing import (mcudb/tools/pinmux_hal_nxp.py).

Run: .venv/Scripts/python -m unittest mcudb/tools/test_pinmux_hal_nxp.py
"""

import shutil
import sys
import tempfile
import unittest
from pathlib import Path
from unittest import mock

import yaml

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))

import pinmux_hal_nxp as gen  # noqa: E402

BASE = """/*
 * NOTE: Autogenerated file by kinetis_cfg_utils.py
 * for TEST_LQFP8/signal_configuration.xml
 *
 * Copyright 2023, NXP
 * SPDX-License-Identifier: Apache-2.0
 */
#define KINETIS_MUX(port, pin, mux) (((port) - 'A') << 28)
#define ADC0_SE0_PTA0 KINETIS_MUX('A',0,0) /* PTA0 */
#define PTA0 KINETIS_MUX('A',0,1) /* PTA0 */
#define CAN0_RX_PTA0 KINETIS_MUX('A',0,5) /* PTA0 */
#define FXIO_D3_PTA0 KINETIS_MUX('A',0,4) /* PTA0 */
#define PTB17 KINETIS_MUX('B',17,1) /* PTB17 */
#define FTM4_CH0_PTB17 KINETIS_MUX('B',17,2) /* PTB17 */
"""

DELTA = """/*
 * NOTE: Autogenerated file by kinetis_cfg_utils.py
 * for TEST_QFN4/signal_configuration.xml
 *
 * Copyright 2023, NXP
 * SPDX-License-Identifier: Apache-2.0
 */
#include "TEST_LQFP8-pinctrl.h"
#undef PTB17
#undef FTM4_CH0_PTB17
#undef FXIO_D3_PTA0
#define FXIO_D3_PTA0 KINETIS_MUX('A',0,6) /* PTA0 */
"""

# SIUL2 format (S32K3): licence notice with an empty comment line, _O/_I pairs, input-only and output-only entries
SIUL2 = """/*
 * Copyright 2023-2026 NXP
 *
 * SPDX-License-Identifier: Apache-2.0
 */
#include <zephyr/dt-bindings/pinctrl/nxp-siul2-pinctrl.h>
#define PTA0_EIRQ0              NXP_SIUL2_PINMUX(0, 0, 0, 0, 16, 1)
#define PTA3_LPSPI1_SCK_O       NXP_SIUL2_PINMUX(0, 0, 3, 3, 0, 0)
#define PTA3_LPSPI1_SCK_I       NXP_SIUL2_PINMUX(0, 0, 3, 0, 238, 1)
#define PTA6_CAN0_RX            NXP_SIUL2_PINMUX(0, 0, 6, 0, 0, 2)
#define PTA7_CAN0_TX            NXP_SIUL2_PINMUX(0, 0, 7, 4, 0, 0)
#define PTB12_EMIOS_0_CH0_X_O   NXP_SIUL2_PINMUX(0, 0, 44, 2, 0, 0)
#define PTB12_EMIOS_0_CH0_X_I   NXP_SIUL2_PINMUX(0, 0, 44, 0, 48, 1)
#define PTC1_FXIO_D1_O          NXP_SIUL2_PINMUX(1, 2, 65, 3, 0, 0)
#define PTA24_GPI24             NXP_SIUL2_PINMUX(0, 0, 23, 0, 24, 0)
#define PTA8_LPUART0_TX_O       NXP_SIUL2_PINMUX(0, 0, 8, 0, 0, 0)
#define TRGMUX_INT_OUT37_EMIOS_0_CH6_G NXP_SIUL2_PINMUX(0, 0, 17, 0, 54, 3)
"""

SIUL2_DELTA = """/*
 * Copyright 2023-2026 NXP
 * SPDX-License-Identifier: Apache-2.0
 */
#include "TEST_257BGA-pinctrl.h"
#undef PTA7_CAN0_TX
#undef PTB12_EMIOS_0_CH0_X_I
"""


class PinmuxHalNxpTest(unittest.TestCase):
    def setUp(self):
        self.tmp = Path(tempfile.mkdtemp())
        (self.tmp / "TEST_LQFP8-pinctrl.h").write_text(BASE, encoding="utf-8")
        (self.tmp / "TEST_QFN4-pinctrl.h").write_text(DELTA, encoding="utf-8")
        (self.tmp / "TEST_257BGA-pinctrl.h").write_text(SIUL2, encoding="utf-8")
        (self.tmp / "TEST_172HDQFP-pinctrl.h").write_text(SIUL2_DELTA, encoding="utf-8")

    def tearDown(self):
        shutil.rmtree(self.tmp, ignore_errors=True)

    def test_base_table_with_normalised_names(self):
        fmt, table, excluded = gen.parse(self.tmp / "TEST_LQFP8-pinctrl.h")
        self.assertEqual((fmt, excluded), ("kinetis", []))
        self.assertEqual(table, {"ADC0_SE0": {"PTA0": 0}, "GPIO": {"PTA0": 1, "PTB17": 1}, "FlexCAN0_RX": {"PTA0": 5},
                                 "FlexIO_D3": {"PTA0": 4}, "FTM4_CH0": {"PTB17": 2}})

    def test_delta_removes_and_changes_signals(self):
        _, table, _ = gen.parse(self.tmp / "TEST_QFN4-pinctrl.h")
        self.assertEqual(table, {"ADC0_SE0": {"PTA0": 0}, "GPIO": {"PTA0": 1}, "FlexCAN0_RX": {"PTA0": 5},
                                 "FlexIO_D3": {"PTA0": 6}})

    def test_inconsistent_entry_is_left_out_and_listed(self):
        (self.tmp / "BAD-pinctrl.h").write_text(BASE.replace("TEST_LQFP8/", "BAD/").replace(
            "FTM4_CH0_PTB17 KINETIS_MUX('B',17,2)", "FTM4_CH0_PTB17 KINETIS_MUX('B',16,2)"), encoding="utf-8")
        _, table, excluded = gen.parse(self.tmp / "BAD-pinctrl.h")
        self.assertNotIn("FTM4_CH0", table)
        self.assertEqual(excluded, ["FTM4_CH0_PTB17 does not match KINETIS_MUX('B',16,2)"])
        with mock.patch.object(gen, "MCUDB", self.tmp.parent):
            _, text = gen.render(self.tmp / "BAD-pinctrl.h")
        self.assertIn("#   FTM4_CH0_PTB17 does not match KINETIS_MUX('B',16,2)\n", text)
        self.assertIn("# Nicht übernommen (1 Einträge", text)

    def test_conflicting_selectors_are_rejected(self):
        (self.tmp / "BAD-pinctrl.h").write_text(BASE.replace("TEST_LQFP8/", "BAD/") +
                                                "#define CAN0_RX_PTA0_ALT KINETIS_MUX('A',0,5)\n"
                                                "#define PTA0_x KINETIS_MUX('A',0,1)\n", encoding="utf-8")
        gen.parse(self.tmp / "BAD-pinctrl.h")      # unmatched names are left out, not a conflict
        (self.tmp / "BAD2-pinctrl.h").write_text(SIUL2.replace(
            "PTA3_LPSPI1_SCK_I       NXP_SIUL2_PINMUX(0, 0, 3, 0, 238, 1)",
            "PTA3_LPSPI1_SCK_I       NXP_SIUL2_PINMUX(0, 0, 3, 0, 238, 1)\n"
            "#define PTA3_LPSPI1_SCK NXP_SIUL2_PINMUX(0, 0, 3, 5, 0, 0)"), encoding="utf-8")
        with self.assertRaisesRegex(gen.SourceError, "LPSPI1_SCK on PTA3 with selectors"):
            gen.parse(self.tmp / "BAD2-pinctrl.h")

    def test_siul2_selectors(self):
        fmt, table, excluded = gen.parse(self.tmp / "TEST_257BGA-pinctrl.h")
        self.assertEqual(fmt, "siul2")
        self.assertEqual(table, {
            "EIRQ0": {"PTA0": {"mscr": 0, "imcr": 16, "imcr_sss": 1}},
            "LPSPI1_SCK": {"PTA3": {"mscr": 3, "mscr_sss": 3, "imcr": 238, "imcr_sss": 1}},
            "FlexCAN0_RX": {"PTA6": {"mscr": 6, "imcr": 0, "imcr_sss": 2}},
            "FlexCAN0_TX": {"PTA7": {"mscr": 7, "mscr_sss": 4}},
            "EMIOS0_CH0": {"PTB12": {"mscr": 44, "mscr_sss": 2, "imcr": 48, "imcr_sss": 1}},
            "FlexIO_D1": {"PTC1": {"mscr": 65, "mscr_sss": 3, "mscr_siul2": 1, "imcr_siul2": 2}},
        })
        self.assertEqual(excluded, [
            "PTA24_GPI24: MSCR index 23 in NXP_SIUL2_PINMUX(0, 0, 23, 0, 24, 0), expected 24 for PTA24",
            "PTA8_LPUART0_TX_O: direction does not match NXP_SIUL2_PINMUX(0, 0, 8, 0, 0, 0)",
            "TRGMUX_INT_OUT37_EMIOS_0_CH6_G: no pin name in NXP_SIUL2_PINMUX(0, 0, 17, 0, 54, 3)",
        ])

    def test_siul2_delta_and_rendering(self):
        _, table, _ = gen.parse(self.tmp / "TEST_172HDQFP-pinctrl.h")
        self.assertNotIn("FlexCAN0_TX", table)
        self.assertEqual(table["EMIOS0_CH0"], {"PTB12": {"mscr": 44, "mscr_sss": 2}})
        with mock.patch.object(gen, "MCUDB", self.tmp.parent):
            part, text = gen.render(self.tmp / "TEST_257BGA-pinctrl.h")
        self.assertEqual(part, "TEST_257BGA")
        self.assertIn("# Copyright 2023-2026 NXP, SPDX-License-Identifier: Apache-2.0\n", text)
        self.assertIn("selector: SIUL2_MSCR/IMCR\n", text)
        self.assertIn("  FlexIO_D1:\n    PTC1: {mscr_siul2: 1, mscr: 65, mscr_sss: 3, imcr_siul2: 2}\n", text)
        doc = yaml.safe_load(text)
        self.assertEqual(doc["signals"]["LPSPI1_SCK"]["PTA3"], {"mscr": 3, "mscr_sss": 3, "imcr": 238, "imcr_sss": 1})

    def test_part_name_and_licence_are_checked(self):
        with mock.patch.object(gen, "MCUDB", self.tmp.parent):
            (self.tmp / "OTHER-pinctrl.h").write_text(BASE, encoding="utf-8")
            with self.assertRaisesRegex(gen.SourceError, "header describes TEST_LQFP8"):
                gen.render(self.tmp / "OTHER-pinctrl.h")
            (self.tmp / "NOLIC-pinctrl.h").write_text(SIUL2.replace("SPDX-License-Identifier: Apache-2.0", ""),
                                                      encoding="utf-8")
            with self.assertRaisesRegex(gen.SourceError, "licence notice not found"):
                gen.render(self.tmp / "NOLIC-pinctrl.h")
        (self.tmp / "MISSING-pinctrl.h").write_text('#include "NOPE-pinctrl.h"\n', encoding="utf-8")
        with self.assertRaisesRegex(gen.SourceError, "NOPE-pinctrl.h not found"):
            gen.parse(self.tmp / "MISSING-pinctrl.h")

    def test_repository_tables_are_up_to_date(self):
        parts = [s.name.removesuffix("-pinctrl.h") for s in gen.sources()]
        # PLAT-11: + S32K116_LQFP48, S32K116_QFN32; TOOL-244: the two S32K3 parts of the private family s32k3xx are
        # missing in the exported open tree
        k3 = (gen.MCUDB / "s32k3xx").is_dir()
        self.assertEqual(len(parts), 19 if k3 else 17)
        self.assertEqual(gen.main(["--check"]), 0)
        part, text = gen.render(gen.sources()[0])
        self.assertEqual(part, "S32K116_LQFP48")
        self.assertIn("SPDX-License-Identifier: Apache-2.0", text)
        for src in gen.sources():
            self.assertTrue((src.parent / "LICENSE").read_text(encoding="utf-8").lstrip().startswith("Apache License"))
        bga = yaml.safe_load((gen.MCUDB / "s32k1xx" / "S32K144_BGA100.pinmux.yaml").read_text(encoding="utf-8"))
        self.assertIn({"PTB0": 5, "PTC2": 3, "PTE4": 5}, [bga["signals"]["FlexCAN0_RX"]])
        # hal_nxp derives the S32K144 LQFP100 from the BGA100 without differences; the own table must say the same
        lqfp = yaml.safe_load((gen.MCUDB / "s32k1xx" / "S32K144_LQFP100.pinmux.yaml").read_text(encoding="utf-8"))
        self.assertEqual(lqfp["signals"], bga["signals"])
        if k3:
            table = yaml.safe_load((gen.MCUDB / "s32k3xx" / "S32K344_K324_K314_257BGA.pinmux.yaml").read_text(encoding="utf-8"))
            self.assertEqual(table["signals"]["FlexCAN0_RX"]["PTA6"], {"mscr": 6, "imcr": 0, "imcr_sss": 2})


if __name__ == "__main__":
    unittest.main()
